    "C06", "C08", "C09", "C15", "C18"
  ],
  "claims": [
    {
      "claim": "Directly measured oral bioavailability in humans/rats for related phenolic natural products is consistently below 20%: chrysin <1% (C02) and predicted 0.003–0.02% (C16); peonidin and petunidin glycosides 0.14–0.48% (C01, C03, C04, C05, C10, C11, C12, C17); curcumin poor/low (C07, C13, C14, C19); flavonolignans very low by CL/F (C06, C08, C09, C15, C18); acacetin poor due to glucuronidation and efflux (C25); 7,8-benzoflavone 13.2% (C26).",
      "card_ids": [
        "C02", "C16", "C01", "C03", "C04", "C05", "C10", "C11", "C12", "C17",
        "C07", "C13", "C14", "C19", "C06", "C08", "C09", "C15", "C18", "C25", "C26"
      ]
    },
    {
      "claim": "L3 oral exposure records are mixed: nobiletin and heptamethoxyflavone show extremely low Cmax (pg/mL) after oral rikkunshito (C31, C32, C34, C36, C37, C40, C41), consistent with low F, whereas naproxen and BHA show higher Cmax (C30, C33, C35, C38, C39) but lack an F endpoint and have limited structural transferability to scopoletin.",
      "card_ids": [
        "C31", "C32", "C34", "C36", "C37", "C40", "C41",
        "C30", "C33", "C35", "C38", "C39"
      ]
    },
    {
      "claim": "No direct scopoletin-specific oral bioavailability or matched oral/IV exposure record is present; the low prediction rests on transferable low-F evidence from related phenolic natural products, which L3 does not overturn.",
      "card_ids": ["C02", "C16", "C25", "C26"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": [
        "C30", "C31", "C32", "C33", "C34", "C35", "C36", "C37", "C38", "C39", "C40", "C41"
      ]
    }
  ],
  "evidence_gaps": [
    "No direct scopoletin-specific oral bioavailability or matched oral/IV pharmacokinetic record is available.",
    "L3 Cmax records lack IV comparators and, for rikkunshito, pure-compound doses, so they cannot be converted into F values.",
    "Structural transfer from polyphenols to scopoletin is uncertain because scopoletin is smaller, more soluble, and has a single phenol.",
    "First-pass glucuronidation/sulfation of the 7-OH and coumarin ring metabolism are inferred, not directly measured for scopoletin."
  ],
  "decision_summary": "L1/L2 provide consistent direct low-F measurements for related phenolic natural products (chrysin <1%, anthocyanins 0.14–0.48%, curcumin poor, flavonolignans very low, 7,8-benzoflavone 13.2%). L3 oral Cmax records are mixed and not endpoint-matched: polymethoxyflavones show extremely low Cmax, while naproxen and BHA show higher Cmax but lack F determination and have limited transferability to scopoletin. The new evidence does not overturn the transferable low-F basis, so the prediction remains low with moderate confidence."
}

